window.PROBLEM_SOURCES["react-03"] = {"id": "react-03", "language": "react", "stub": {"path": "react/practice_problems/problem_03_alert_triage_console.jsx", "source": "/**\n * =============================================================================\n * INTERVIEW PROBLEM 3: Alert Triage Console\n * Difficulty: Senior Software Engineer | Estimated time: 45–60 min\n * =============================================================================\n *\n * CONTEXT\n * -------\n * You're building the dispatch operations console for an emergency-response\n * platform. Incoming alerts from radio dispatch and field sensors stream in\n * continuously. Operators triage them by assigning to available field units\n * or acknowledging alerts that don't require dispatch.\n *\n * A working mock alert stream, available units, and API stubs are provided.\n * Do NOT modify anything in the \"PROVIDED — DO NOT MODIFY\" sections.\n *\n * =============================================================================\n *\n * PART 1 — Alert queue  (~15 min)\n * ────────────────────────────────\n * Render an <AlertTriageConsole /> component that:\n *   - Subscribes to `alertStream` on mount and unsubscribes on unmount.\n *   - Displays unacknowledged, unassigned alerts sorted by severity descending\n *     (5 = highest), then by timestamp ascending (oldest first within same sev).\n *   - Each row shows: severity badge (1–5, color-coded), alert type, message,\n *     source, and relative time (\"3 min ago\").\n *\n * Data-testid requirements (Playwright relies on these):\n *   data-testid=\"alert-row\"      — wrapper element for each alert row\n *   data-testid=\"severity-badge\" — the severity indicator inside each row\n *\n * PART 2 — Assign to unit  (~15 min)\n * ────────────────────────────────────\n * Add an assign action to each unassigned, unacknowledged alert row:\n *   - A <select data-testid=\"unit-select\"> populated with UNITS.\n *   - A <button data-testid=\"assign-btn\"> that calls assignAlert(alertId, unitId).\n *\n * When the assignment succeeds:\n *   - Show the assigned unit name on the row (no separate section needed yet).\n *   - Mark the alert as assigned in local state.\n * On failure (~15% of the time):\n *   - Revert to unassigned; show an inline error (\"Assignment failed — retry\").\n * While in-flight:\n *   - Disable the assign button and the unit select.\n *\n * PART 3 — Tab navigation and bulk-ack  (~15 min)\n * ─────────────────────────────────────────────────\n * Add a tab bar at the top of the console with three tabs:\n *   Queued | Assigned | Acknowledged\n *\n * Data-testid requirements:\n *   data-testid=\"tab-queued\"        — Queued tab button\n *   data-testid=\"tab-assigned\"      — Assigned tab button\n *   data-testid=\"tab-acknowledged\"  — Acknowledged tab button\n *\n * Each tab shows its count in parentheses, e.g. \"Queued (3)\".\n *\n * Switching tabs changes which alerts are shown:\n *   Queued       — unassigned AND not acknowledged\n *   Assigned     — assigned AND not acknowledged\n *   Acknowledged — acknowledged (by any means)\n *\n * On the Queued tab, add an \"Ack All\" button (data-testid=\"ack-all-btn\") that\n * calls acknowledgeAlert(id) for every currently visible queued alert and marks\n * them all as acknowledged. Fire all calls in parallel (Promise.all or similar).\n *\n * =============================================================================\n */\n\nimport React, { useState, useEffect, useMemo, useCallback } from 'react'\n\n// =============================================================================\n// PROVIDED — DO NOT MODIFY\n// =============================================================================\n\nexport const ALERT_TYPES = ['radio-dispatch', 'sensor-alert', 'social-monitor', 'field-report']\n\nexport const SEVERITY_COLORS = {\n  5: { background: '#fef2f2', color: '#991b1b', border: '#fca5a5', label: 'P1' },\n  4: { background: '#fff7ed', color: '#9a3412', border: '#fdba74', label: 'P2' },\n  3: { background: '#fefce8', color: '#854d0e', border: '#fde047', label: 'P3' },\n  2: { background: '#eff6ff', color: '#1e40af', border: '#93c5fd', label: 'P4' },\n  1: { background: '#f0fdf4', color: '#166534', border: '#86efac', label: 'P5' },\n}\n\n/**\n * Available field units that alerts can be dispatched to.\n */\nexport const UNITS = [\n  { id: 'unit-12', name: 'Alpha Team',  type: 'patrol' },\n  { id: 'unit-14', name: 'Beta Team',   type: 'patrol' },\n  { id: 'unit-21', name: 'Fire Unit 3', type: 'fire'   },\n  { id: 'unit-33', name: 'Medic 5',     type: 'ems'    },\n  { id: 'unit-45', name: 'SWAT Alpha',  type: 'swat'   },\n]\n\n/**\n * Deterministic seed alerts — appear immediately on connect.\n * Playwright tests rely on the message text and severity values here.\n */\nexport const SEED_ALERTS = [\n  {\n    id:           'alt-s1',\n    type:         'radio-dispatch',\n    severity:     5,\n    message:      'Reports of shots fired at Central Station',\n    source:       'radio-north',\n    ts:           new Date(Date.now() - 1  * 60_000).toISOString(),\n    assignedTo:   null,\n    acknowledged: false,\n  },\n  {\n    id:           'alt-s2',\n    type:         'sensor-alert',\n    severity:     4,\n    message:      'Collision detected on Highway 12',\n    source:       'sensor-grid-east',\n    ts:           new Date(Date.now() - 3  * 60_000).toISOString(),\n    assignedTo:   null,\n    acknowledged: false,\n  },\n  {\n    id:           'alt-s3',\n    type:         'radio-dispatch',\n    severity:     3,\n    message:      'Structural fire reported at Warehouse District',\n    source:       'radio-south',\n    ts:           new Date(Date.now() - 6  * 60_000).toISOString(),\n    assignedTo:   null,\n    acknowledged: false,\n  },\n  {\n    id:           'alt-s4',\n    type:         'sensor-alert',\n    severity:     2,\n    message:      'Flooding sensors triggered at Riverside Park',\n    source:       'sensor-grid-west',\n    ts:           new Date(Date.now() - 10 * 60_000).toISOString(),\n    assignedTo:   null,\n    acknowledged: false,\n  },\n]\n\nlet _alertId = 100\n\nconst MESSAGES = {\n  'radio-dispatch': [\n    'Officer requesting backup at intersection of 5th and Main',\n    'Suspicious vehicle reported near school zone',\n    'Domestic disturbance call in progress',\n  ],\n  'sensor-alert': [\n    'Gunshot detection triggered — confidence 87%',\n    'Traffic sensor anomaly on Bridge Road',\n    'Environmental sensor spike at industrial zone',\n  ],\n  'social-monitor': [\n    'Spike in 911-related social posts — downtown area',\n    'Crowd incident reported via social media',\n  ],\n  'field-report': [\n    'Officer on scene — requesting additional units',\n    'Situation escalating — requesting supervisor',\n  ],\n}\n\nfunction makeRandomAlert() {\n  const type     = ALERT_TYPES[Math.floor(Math.random() * ALERT_TYPES.length)]\n  const msgs     = MESSAGES[type]\n  const severity = Math.ceil(Math.random() * 5)\n  return {\n    id:           `alt-${_alertId++}`,\n    type,\n    severity,\n    message:      msgs[Math.floor(Math.random() * msgs.length)],\n    source:       `source-${Math.floor(Math.random() * 10)}`,\n    ts:           new Date().toISOString(),\n    assignedTo:   null,\n    acknowledged: false,\n  }\n}\n\n/**\n * createAlertStream() → { connect, disconnect, subscribe }\n *\n * connect()           — seed alerts arrive within 300ms, then new random\n *                       alerts every 2.5s\n * disconnect()        — stop emitting\n * subscribe(handler)  — returns unsubscribe fn\n */\nexport function createAlertStream() {\n  let handlers = []\n  let timerId  = null\n\n  function emit(alert) {\n    handlers.forEach(h => h({ ...alert }))\n  }\n\n  return {\n    connect() {\n      SEED_ALERTS.forEach((alert, i) => setTimeout(() => emit(alert), i * 50))\n      timerId = setInterval(() => emit(makeRandomAlert()), 2500)\n    },\n    disconnect() {\n      clearInterval(timerId)\n      timerId = null\n    },\n    subscribe(handler) {\n      handlers.push(handler)\n      return () => { handlers = handlers.filter(h => h !== handler) }\n    },\n  }\n}\n\n/**\n * assignAlert(alertId, unitId) → Promise<void>\n * Simulates a POST /alerts/:id/assign API call.\n * Resolves after ~400ms. Rejects ~15% of the time.\n */\nexport function assignAlert(alertId, unitId) {\n  return new Promise((resolve, reject) => {\n    setTimeout(() => {\n      Math.random() < 0.15\n        ? reject(new Error(`Failed to assign ${alertId} to ${unitId}`))\n        : resolve()\n    }, 400)\n  })\n}\n\n/**\n * acknowledgeAlert(alertId) → Promise<void>\n * Always resolves after ~300ms.\n */\nexport function acknowledgeAlert(alertId) {\n  return new Promise(resolve => setTimeout(resolve, 300))\n}\n\n// Shared singleton — import this in your component\nexport const alertStream = createAlertStream()\n\n// =============================================================================\n// YOUR WORK STARTS HERE\n// =============================================================================\n\n// ---------------------------------------------------------------------------\n// PART 1 — Implement AlertTriageConsole\n// ---------------------------------------------------------------------------\n\nexport function AlertTriageConsole() {\n  // TODO Part 1: subscribe to alertStream on mount, unsubscribe on unmount.\n  //              Store alerts in state. On the default view, display queued\n  //              alerts sorted by severity desc, then ts asc.\n  //              Each row: data-testid=\"alert-row\"\n  //              Severity badge: data-testid=\"severity-badge\"\n\n  // TODO Part 2: add assign action per queued row.\n  //              Unit select: data-testid=\"unit-select\"\n  //              Assign button: data-testid=\"assign-btn\"\n  //              Disable both while request is in-flight.\n\n  // TODO Part 3: add tab bar and Ack All button.\n  //              Tabs: data-testid=\"tab-queued\", \"tab-assigned\", \"tab-acknowledged\"\n  //              Ack All: data-testid=\"ack-all-btn\" (visible on Queued tab only)\n\n  return (\n    <div style={{ fontFamily: 'system-ui', maxWidth: 900, margin: '0 auto', padding: 24 }}>\n      <h2 style={{ marginBottom: 16 }}>Alert Triage Console</h2>\n\n      {/* TODO: tab bar (Part 3) */}\n\n      {/* TODO: Ack All button (Part 3, Queued tab only) */}\n\n      {/* TODO: alert list (Part 1) */}\n      <p style={{ color: '#94a3b8' }}>No alerts yet.</p>\n    </div>\n  )\n}\n\n// ---------------------------------------------------------------------------\n// Suggested sub-components (optional — structure however you like)\n// ---------------------------------------------------------------------------\n\n// function TabBar({ activeTab, counts, onTabChange }) { ... }\n// function AlertRow({ alert, units, onAssign, onAcknowledge }) { ... }\n\n// ---------------------------------------------------------------------------\n// App entry point\n// ---------------------------------------------------------------------------\n\nexport default function App() {\n  useEffect(() => {\n    alertStream.connect()\n    return () => alertStream.disconnect()\n  }, [])\n\n  return <AlertTriageConsole />\n}\n"}, "test": {"path": "react/tests/test_problem_03_alert_triage_console.spec.js", "source": "/**\n * Playwright tests for Problem 03 — Alert Triage Console\n *\n * Run (from react/):\n *   npm run test:03\n *\n * These tests target a COMPLETED implementation of src/App.jsx.\n * Against the stub they will fail — that is expected behaviour.\n *\n * Copy the problem to activate:\n *   cp practice_problems/problem_03_alert_triage_console.jsx src/App.jsx\n *\n * Seed data reference (from SEED_ALERTS in the problem file):\n *   alt-s1  radio-dispatch  sev=5  \"Reports of shots fired at Central Station\"\n *   alt-s2  sensor-alert    sev=4  \"Collision detected on Highway 12\"\n *   alt-s3  radio-dispatch  sev=3  \"Structural fire reported at Warehouse District\"\n *   alt-s4  sensor-alert    sev=2  \"Flooding sensors triggered at Riverside Park\"\n *\n * Determinism: these tests own the page's clock and `Math.random` (see\n * tests/helpers/deterministic.js). Seed alerts appear because the test advances\n * 300 ms, the 2500 ms random-alert interval never fires, and `assignAlert`\n * succeeds or rejects because the test chose which.\n */\n\nimport { test, expect } from '@playwright/test'\nimport {\n  installDeterminism,\n  deliverSeedData,\n  settleRequest,\n  RANDOM_FAILURE,\n} from './helpers/deterministic.js'\n\nconst HEADING = /alert triage console/i\n\n/** The four documented seed alerts, all queued and none acknowledged. */\nconst SEED_COUNT = 4\n\ntest.describe('Problem 03 — Alert Triage Console', () => {\n  test.beforeEach(async ({ page }) => {\n    await installDeterminism(page)\n  })\n\n  // ── Part 1: alert queue ────────────────────────────────────────────────────\n\n  test('renders the Alert Triage Console heading', async ({ page }) => {\n    await expect(page.getByRole('heading', { name: HEADING })).toBeVisible()\n  })\n\n  test('seed alerts appear in the list', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    await expect(page.locator('[data-testid=\"alert-row\"]')).toHaveCount(SEED_COUNT)\n  })\n\n  test('each alert row contains a severity badge', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    await expect(page.locator('[data-testid=\"severity-badge\"]')).toHaveCount(SEED_COUNT)\n  })\n\n  test('seed alert message text appears in the list', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    await expect(page.locator('body')).toContainText('Central Station')\n    await expect(page.locator('body')).toContainText('Highway 12')\n  })\n\n  test('alerts are sorted highest severity first', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    await expect(page.locator('[data-testid=\"alert-row\"]')).toHaveCount(SEED_COUNT)\n    const firstBadgeText = await page.locator('[data-testid=\"severity-badge\"]').first().textContent()\n    expect(firstBadgeText).toMatch(/5|P1|critical/i)\n    // The whole ordering, not just the head: severities 5, 4, 3, 2. Only\n    // knowable because no random alert can slip into the list.\n    const rowText = await page.locator('[data-testid=\"alert-row\"]').first().textContent()\n    expect(rowText).toContain('Central Station')\n  })\n\n  // ── Part 2: assign to unit ─────────────────────────────────────────────────\n\n  test('unit select is present on each unassigned row', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    await expect(page.locator('[data-testid=\"unit-select\"]')).toHaveCount(SEED_COUNT)\n  })\n\n  test('assign button is present on each unassigned row', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    await expect(page.locator('[data-testid=\"assign-btn\"]')).toHaveCount(SEED_COUNT)\n  })\n\n  test('unit select is populated with available units', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    const options = await page.locator('[data-testid=\"unit-select\"]').first().locator('option').allTextContents()\n    expect(options.join(' ')).toMatch(/Alpha Team|Beta Team|Fire Unit/i)\n  })\n\n  test('assign button and unit select are disabled while request is in-flight', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    const sel = page.locator('[data-testid=\"unit-select\"]').first()\n    await sel.selectOption({ index: 1 })\n    const btn = page.locator('[data-testid=\"assign-btn\"]').first()\n    await btn.click()\n    // The request cannot settle: no time passes until a test advances it.\n    await expect(btn).toBeDisabled()\n    await expect(sel).toBeDisabled()\n  })\n\n  test('a successful assignment moves the alert to the Assigned tab', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    await page.locator('[data-testid=\"unit-select\"]').first().selectOption({ index: 1 })\n    await page.locator('[data-testid=\"assign-btn\"]').first().click()\n    await settleRequest(page)\n\n    await expect(page.locator('[data-testid=\"alert-row\"]')).toHaveCount(SEED_COUNT - 1)\n    await page.getByTestId('tab-assigned').click()\n    await expect(page.locator('[data-testid=\"alert-row\"]')).toHaveCount(1)\n    await expect(page.locator('body')).toContainText('Beta Team')\n  })\n\n  test('a rejected assignment reverts the alert and shows an inline error', async ({ page }) => {\n    // Previously untestable: the reject branch fired at random. Pinning\n    // Math.random below the 0.15 threshold makes the rollback path assertable.\n    await installDeterminism(page, { random: RANDOM_FAILURE })\n    await deliverSeedData(page, HEADING)\n    await page.locator('[data-testid=\"unit-select\"]').first().selectOption({ index: 1 })\n    await page.locator('[data-testid=\"assign-btn\"]').first().click()\n    await settleRequest(page)\n\n    await expect(page.locator('body')).toContainText(/assignment failed/i)\n    await expect(page.locator('[data-testid=\"alert-row\"]')).toHaveCount(SEED_COUNT)\n  })\n\n  // ── Part 3: tab bar and bulk-ack ──────────────────────────────────────────\n\n  test('Queued tab is present and visible', async ({ page }) => {\n    await expect(page.getByTestId('tab-queued')).toBeVisible()\n  })\n\n  test('Assigned tab is present and visible', async ({ page }) => {\n    await expect(page.getByTestId('tab-assigned')).toBeVisible()\n  })\n\n  test('Acknowledged tab is present and visible', async ({ page }) => {\n    await expect(page.getByTestId('tab-acknowledged')).toBeVisible()\n  })\n\n  test('tabs show their counts', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    // Exact counts are only assertable because the alert set is frozen.\n    await expect(page.getByTestId('tab-queued')).toContainText(`(${SEED_COUNT})`)\n    await expect(page.getByTestId('tab-assigned')).toContainText('(0)')\n    await expect(page.getByTestId('tab-acknowledged')).toContainText('(0)')\n  })\n\n  test('Ack All button is visible on the Queued tab', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    await expect(page.getByTestId('ack-all-btn')).toBeVisible()\n  })\n\n  test('switching to Assigned tab hides unassigned rows', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    await page.getByTestId('tab-assigned').click()\n    await expect(page.locator('[data-testid=\"alert-row\"]')).toHaveCount(0)\n  })\n\n  test('Ack All acknowledges all visible queued alerts', async ({ page }) => {\n    await deliverSeedData(page, HEADING)\n    await expect(page.locator('[data-testid=\"alert-row\"]')).toHaveCount(SEED_COUNT)\n\n    await page.getByTestId('ack-all-btn').click()\n    await settleRequest(page)\n\n    await expect(page.locator('[data-testid=\"alert-row\"]')).toHaveCount(0)\n\n    await page.getByTestId('tab-acknowledged').click()\n    // Exactly the four that were queued: no alert can have arrived meanwhile.\n    await expect(page.locator('[data-testid=\"alert-row\"]')).toHaveCount(SEED_COUNT)\n  })\n})\n"}, "parts": [{"part": 1, "source": " * PART 1 — Alert queue  (~15 min)\n * ────────────────────────────────\n * Render an <AlertTriageConsole /> component that:\n *   - Subscribes to `alertStream` on mount and unsubscribes on unmount.\n *   - Displays unacknowledged, unassigned alerts sorted by severity descending\n *     (5 = highest), then by timestamp ascending (oldest first within same sev).\n *   - Each row shows: severity badge (1–5, color-coded), alert type, message,\n *     source, and relative time (\"3 min ago\").\n *\n * Data-testid requirements (Playwright relies on these):\n *   data-testid=\"alert-row\"      — wrapper element for each alert row\n *   data-testid=\"severity-badge\" — the severity indicator inside each row\n *\n *\n"}, {"part": 2, "source": " * PART 2 — Assign to unit  (~15 min)\n * ────────────────────────────────────\n * Add an assign action to each unassigned, unacknowledged alert row:\n *   - A <select data-testid=\"unit-select\"> populated with UNITS.\n *   - A <button data-testid=\"assign-btn\"> that calls assignAlert(alertId, unitId).\n *\n * When the assignment succeeds:\n *   - Show the assigned unit name on the row (no separate section needed yet).\n *   - Mark the alert as assigned in local state.\n * On failure (~15% of the time):\n *   - Revert to unassigned; show an inline error (\"Assignment failed — retry\").\n * While in-flight:\n *   - Disable the assign button and the unit select.\n *\n *\n"}, {"part": 3, "source": " * PART 3 — Tab navigation and bulk-ack  (~15 min)\n * ─────────────────────────────────────────────────\n * Add a tab bar at the top of the console with three tabs:\n *   Queued | Assigned | Acknowledged\n *\n * Data-testid requirements:\n *   data-testid=\"tab-queued\"        — Queued tab button\n *   data-testid=\"tab-assigned\"      — Assigned tab button\n *   data-testid=\"tab-acknowledged\"  — Acknowledged tab button\n *\n * Each tab shows its count in parentheses, e.g. \"Queued (3)\".\n *\n * Switching tabs changes which alerts are shown:\n *   Queued       — unassigned AND not acknowledged\n *   Assigned     — assigned AND not acknowledged\n *   Acknowledged — acknowledged (by any means)\n *\n * On the Queued tab, add an \"Ack All\" button (data-testid=\"ack-all-btn\") that\n * calls acknowledgeAlert(id) for every currently visible queued alert and marks\n * them all as acknowledged. Fire all calls in parallel (Promise.all or similar).\n *\n"}], "implementationSurface": "}\n\n      {/* TODO: Ack All button (Part 3, Queued tab only) */}\n\n      {/* TODO: alert list (Part 1) */}\n      <p style={{ color: '#94a3b8' }}>No alerts yet.</p>\n    </div>\n  )\n}\n\n// ---------------------------------------------------------------------------\n// Suggested sub-components (optional — structure however you like)\n// ---------------------------------------------------------------------------\n\n// function TabBar({ activeTab, counts, onTabChange }) { ... }\n// function AlertRow({ alert, units, onAssign, onAcknowledge }) { ... }\n\n// ---------------------------------------------------------------------------\n// App entry point\n// ---------------------------------------------------------------------------\n\nexport default function App() {\n  useEffect(() => {\n    alertStream.connect()\n    return () => alertStream.disconnect()\n  }, [])\n\n  return <AlertTriageConsole />\n}\n"};
